"""INTEGRATION-ADAPTER: map 1 km runoff depths to 30 m river segments."""

from __future__ import annotations

import csv
import json
from collections import defaultdict
from pathlib import Path


OUTPUT_FIELDS = (
    "time",
    "unit_id",
    "RS",
    "RI",
    "RG",
    "glacier_fast",
    "glacier_slow",
    "glacier_base",
)
COMPONENTS = (
    "RS",
    "RI",
    "RG",
    "glacier_fast",
    "glacier_slow",
    "glacier_base",
)


def _read_component(row: dict[str, str], component: str) -> float:
    """Accept runoff-side *_mm fields and routing-side component fields."""
    value = row.get(f"{component}_mm", row.get(component, "0"))
    return 0.0 if value in (None, "") else float(value)


def aggregate_runoff_to_reach_segments(
    runoff_path: str | Path,
    mapping_path: str | Path,
    topology_path: str | Path,
    output_path: str | Path,
) -> dict[str, float | int]:
    """Convert 1 km grid depths to reach-segment depths by area-weighted volume.

    The topology unit is the local drainage area assigned to one 30 m-derived
    river reach.  The output therefore represents lateral inflow generated by
    that reach segment, not a separate 1 km subbasin routing calculation.
    """

    with Path(mapping_path).open("r", encoding="utf-8-sig", newline="") as handle:
        mapping_rows = list(csv.DictReader(handle))
    weights_by_grid: dict[str, list[tuple[str, float]]] = defaultdict(list)
    for row in mapping_rows:
        weights_by_grid[row["grid_id"]].append(
            (row["unit_id"], float(row["adjusted_overlap_area_km2"]))
        )

    topology = json.loads(Path(topology_path).read_text(encoding="utf-8"))
    area_by_unit = {row["unit_id"]: float(row["area_km2"]) for row in topology["units"]}
    volumes: dict[tuple[str, str], dict[str, float]] = defaultdict(
        lambda: {component: 0.0 for component in COMPONENTS}
    )
    times = set()
    input_volumes = {component: 0.0 for component in COMPONENTS}

    with Path(runoff_path).open("r", encoding="utf-8-sig", newline="") as handle:
        for row in csv.DictReader(handle):
            grid_id = row["unit_id"]
            if grid_id not in weights_by_grid:
                raise ValueError(f"runoff grid {grid_id} is missing from mapping")
            time = row["time"]
            times.add(time)
            for unit_id, adjusted_area in weights_by_grid[grid_id]:
                for component in COMPONENTS:
                    depth = _read_component(row, component)
                    volume = depth * adjusted_area
                    volumes[(time, unit_id)][component] += volume
                    input_volumes[component] += volume

    output_path = Path(output_path)
    output_path.parent.mkdir(parents=True, exist_ok=True)
    output_volumes = {component: 0.0 for component in COMPONENTS}
    row_count = 0
    with output_path.open("w", encoding="utf-8", newline="") as handle:
        writer = csv.DictWriter(handle, fieldnames=OUTPUT_FIELDS)
        writer.writeheader()
        for time in sorted(times):
            for unit_id in sorted(area_by_unit):
                component_volumes = volumes[(time, unit_id)]
                output_row = {"time": time, "unit_id": unit_id}
                for component in COMPONENTS:
                    depth = component_volumes[component] / area_by_unit[unit_id]
                    output_row[component] = depth
                    output_volumes[component] += depth * area_by_unit[unit_id]
                writer.writerow(output_row)
                row_count += 1

    max_volume_error = max(
        abs(input_volumes[component] - output_volumes[component]) for component in COMPONENTS
    )
    return {
        "output_row_count": row_count,
        "time_count": len(times),
        "routing_unit_count": len(area_by_unit),
        "input_component_volume_mm_km2": input_volumes,
        "output_component_volume_mm_km2": output_volumes,
        "max_component_volume_error_mm_km2": max_volume_error,
        "routing_method": "REACH_SEGMENT",
        "mapping_method": "D8_FLOW_PATH_AREA_OVERLAP",
        "component_fields": list(COMPONENTS),
    }


def aggregate_runoff_to_routing_units(
    runoff_path: str | Path,
    mapping_path: str | Path,
    topology_path: str | Path,
    output_path: str | Path,
) -> dict[str, float | int | str | list[str]]:
    """Backward-compatible name for the reach-segment adapter."""
    return aggregate_runoff_to_reach_segments(
        runoff_path, mapping_path, topology_path, output_path
    )
